const body = $input.first().json.body;

const entry = body?.entry?.[0];
const entryId = entry?.id || '';
const origemInterna = entryId === 'STORICO_INTERNAL';
const change = entry?.changes?.[0];
const value = change?.value;

if (!value?.messages || value.messages.length === 0) {
  return { json: { telefone: null, ignorar: true } };
}

const msg = value.messages[0];

const telefoneCompleto = msg.from;
if (!telefoneCompleto) {
  return { json: { telefone: null, ignorar: true } };
}

let telefoneParaBusca = telefoneCompleto;
// Remove + se presente antes de normalizar
const telefoneSemPlus = telefoneCompleto.startsWith('+') ? telefoneCompleto.substring(1) : telefoneCompleto;
if (telefoneSemPlus.startsWith('55')) {
  const semCodPais = telefoneSemPlus.substring(2);
  const ddd = semCodPais.substring(0, 2);
  const numero = semCodPais.substring(2);
  if (numero.length === 8) {
    telefoneParaBusca = ddd + '9' + numero;
  } else {
    telefoneParaBusca = semCodPais;
  }
}

let mensagemTexto = '';
let tipoMensagem = msg.type;
let buttonReplyId = null;
let listReplyId = null;

if (msg.type === 'text') {
  mensagemTexto = msg.text?.body?.trim().toUpperCase() || '';
} else if (msg.type === 'interactive') {
  const buttonReply = msg.interactive?.button_reply;
  const listReply = msg.interactive?.list_reply;
  if (buttonReply) {
    buttonReplyId = buttonReply.id;
    if (buttonReplyId.startsWith('quiz_') && buttonReplyId !== 'quiz_trigger') {
      mensagemTexto = buttonReplyId.replace('quiz_', '');
    }
  } else if (listReply) {
    listReplyId = listReply.id;
  }
} else if (msg.type === 'button') {
  // Resposta de botão de template da Meta
  // O único template com botão no Stórico é o 'welcome' (Acessar Aula)
  // que sempre deve iniciar a aula — payload pode vir vazio nesse caso
  const payload = msg.button?.payload || '';
  buttonReplyId = payload || 'quiz_trigger_onboarding';
}

return {
  json: {
    telefone: telefoneParaBusca,
    telefone_original: telefoneCompleto,
    mensagem_texto: mensagemTexto,
    tipo_mensagem: tipoMensagem,
    button_reply_id: buttonReplyId,
    list_reply_id: listReplyId,
    ignorar: false,
    origem_interna: origemInterna
  }
};

const usuario = $input.first().json;
const dadosMsg = $('Extrair Dados da Mensagem').first().json;
const mensagemOriginal = dadosMsg.mensagem_texto;
const buttonReplyId = dadosMsg.button_reply_id;
const listReplyId = dadosMsg.list_reply_id;

if (!usuario || !usuario.id) {
  return { json: { usuario_encontrado: false } };
}

const status = usuario.status || 'aguardando_primeiro_contato';
// Verificar se trial expirou pela data (independente do valor salvo no banco)
const trialFim = usuario.trial_fim ? new Date(usuario.trial_fim) : null;
const agora = new Date();
const statusFinal = (status === 'ativo' && usuario.plano !== 'pago' && trialFim && agora > trialFim) ? 'trial_expirado' : status;
const nome = usuario.nome ? usuario.nome.split(' ')[0] : 'Usuário';
const tema = usuario.tema_escolhido || 'Egito Antigo';
const momento = usuario.momento_dia || 'Ao acordar';
const telefone = usuario.telefone;

const horarioMap = {
  'Ao acordar': '6h',
  'Na hora do almoço': '12h',
  'À noite': '19h'
};
const horarioTexto = horarioMap[momento] || '6h';

return {
  json: {
    usuario_encontrado: true,
    status: statusFinal,
    nome,
    tema,
    momento,
    horario_texto: horarioTexto,
    telefone,
    usuario_id: usuario.id,
    aula_atual: usuario.aula_atual || 0,
    quiz_pendente_aula_id: usuario.quiz_pendente_aula_id || null,
    streak_atual: usuario.streak_atual || 0,
    acao_pendente: usuario.acao_pendente || null,
    mensagem_original: mensagemOriginal,
    button_reply_id: buttonReplyId,
    list_reply_id: listReplyId,
    origem_interna: dadosMsg.origem_interna || false
  }
};

const dados = $input.first().json;
let telefone = dados.telefone;
if (!telefone.startsWith('55')) telefone = '55' + telefone;
if (!telefone.startsWith('+')) telefone = '+' + telefone;
return { json: { telefone, tema: dados.tema, aula_atual: dados.aula_atual } };

const dados = $('Extrair Status do Usuário').first().json;
let telefone = dados.telefone;
if (!telefone.startsWith('55')) telefone = '55' + telefone;
if (!telefone.startsWith('+')) telefone = '+' + telefone;

const mensagem1 = `Olá, ${dados.nome}! 👋

Sua jornada em *${dados.tema}* começa agora com aulas enviadas *${dados.momento}*, direto no seu WhatsApp.`;

const mensagem2 = `Todos os dias você vai receber:

🎧 Um áudio narrado
🖼 Imagens para visualizar o que está sendo contado
🧠 Um quiz rápido para fixar o conteúdo`;

const btn3_payload = JSON.stringify({
  messaging_product: 'whatsapp',
  to: telefone,
  type: 'interactive',
  interactive: {
    type: 'button',
    body: { text: 'Sempre que precisar acessar o menu, é só enviar qualquer mensagem para mim. Bora pra sua primeira aula?' },
    action: {
      buttons: [
        { type: 'reply', reply: { id: 'quiz_trigger_onboarding', title: 'Iniciar primeira aula' } }
      ]
    }
  }
});
return { json: { telefone, mensagem1, mensagem2, btn3_payload, usuario_id: dados.usuario_id } };

const dadosWebhook = $('Extrair Dados da Mensagem').first().json;
let telefone = dadosWebhook.telefone_original || dadosWebhook.telefone;
if (telefone && !telefone.startsWith('55')) telefone = '55' + telefone;
if (telefone && !telefone.startsWith('+')) telefone = '+' + telefone;
const mensagem1 = `Olá! 👋

Para começar no Stórico, você precisa se cadastrar primeiro.

Acesse: https://storico.com.br/quiz.html

Lá você escolhe seu tema favorito e horário preferido.

Até logo! 🏛️`;
return { json: { telefone, mensagem1, usuario_id: null } };

const dados = $('Extrair Status do Usuário').first().json;
const msg = dados.mensagem_original || '';
const buttonReplyId = dados.button_reply_id || null;
const listReplyId = dados.list_reply_id || null;
const acaoPendente = dados.acao_pendente || null;

let rota = 'outro';

// Botões e listas têm prioridade
if (buttonReplyId === 'quiz_trigger_onboarding' || buttonReplyId === 'Acessar Aula') {
  rota = 'iniciar_aula';
} else if (buttonReplyId === 'quiz_trigger' || (buttonReplyId && buttonReplyId.startsWith('quiz_trigger_') && buttonReplyId !== 'quiz_trigger_onboarding')) {
  rota = 'acessar_quiz';
} else if (['quiz_A','quiz_B','quiz_C'].includes(buttonReplyId)) {
  rota = 'resposta_quiz';
} else if (buttonReplyId === 'horario_manha') {
  rota = 'confirmar_manha';
} else if (buttonReplyId === 'horario_almoco') {
  rota = 'confirmar_almoco';
} else if (buttonReplyId === 'horario_noite') {
  rota = 'confirmar_noite';
} else if (listReplyId === 'menu_como_funciona') {
  rota = 'como_funciona';
} else if (listReplyId === 'menu_alterar_horario') {
  rota = 'mudar_horario';
} else if (listReplyId === 'menu_alterar_tema') {
  rota = 'alterar_tema';
} else if (listReplyId === 'menu_suporte') {
  rota = 'suporte';
} else if (listReplyId && listReplyId.startsWith('tema_')) {
  rota = 'confirmar_tema';
} else if (acaoPendente === 'mudando_horario') {
  if (msg === '1') rota = 'confirmar_manha';
  else if (msg === '2') rota = 'confirmar_almoco';
  else if (msg === '3') rota = 'confirmar_noite';
  else rota = 'outro';
} else {
  if (['A','B','C'].includes(msg)) rota = 'resposta_quiz';
  else rota = 'outro';
}

const lista_payload = JSON.stringify({
  messaging_product: 'whatsapp',
  to: dados.telefone,
  type: 'interactive',
  interactive: {
    type: 'list',
    body: { text: '🎯 *Alterar tema*\n\nVocê pode trocar de tema a qualquer momento. Seu progresso em cada tema fica salvo e você volta de onde parou.\n\nEscolha abaixo o tema que quer estudar agora:' },
    action: {
      button: 'Ver temas',
      sections: [{
        title: 'Temas disponíveis',
        rows: [
          { id: 'tema_egito', title: '🐪 Egito Antigo' },
          { id: 'tema_roma', title: '🏛️ Império Romano' },
          { id: 'tema_medieval', title: '⚔️ Idade Média' },
          { id: 'tema_brasil_colonial', title: '🇧🇷 Brasil Colonial' },
          { id: 'tema_segunda_guerra', title: '🪖 Segunda Guerra Mundial' }
        ]
      }]
    }
  }
});
// Extrair aula_id do botão de quiz se disponível
const quizAulaId = (buttonReplyId && buttonReplyId.startsWith('quiz_trigger_') && buttonReplyId !== 'quiz_trigger_onboarding')
  ? buttonReplyId.replace('quiz_trigger_', '')
  : null;

return { json: { ...dados, rota, list_reply_id: listReplyId, lista_payload, quiz_aula_id: quizAulaId } };

const aula = $input.first().json;
const usuario = $('Rotear Mensagem do Usuário').first().json;
let telefone = usuario.telefone;
if (!telefone.startsWith('55')) telefone = '55' + telefone;
if (!telefone.startsWith('+')) telefone = '+' + telefone;

if (!aula || !aula.id) {
  return {
    json: {
      telefone,
      aula_encontrada: false,
      usuario_id: usuario.usuario_id,
      mensagem_conclusao: `Parabéns, ${usuario.nome}! 🥇 Você concluiu todas as 30 aulas de *${usuario.tema}* e se tornou um Expert! Escolha seu próximo tema abaixo.`
    }
  };
}

const imagens = aula.imagens || [];
return {
  json: {
    aula_encontrada: true,
    telefone,
    usuario_id: usuario.usuario_id,
    aula_id: aula.id,
    aula_numero: aula.numero,
    audio_url: aula.audio_url || null,
    imagem_1: imagens[0] || null,
    imagem_2: imagens[1] || null,
    imagem_3: imagens[2] || null,
    mensagem_intro: aula.descricao || '',
    quiz: aula.quiz,
    novo_aula_atual: aula.numero,
    quiz_payload: JSON.stringify({
      messaging_product: 'whatsapp',
      to: telefone,
      type: 'interactive',
      interactive: {
        type: 'button',
        body: { text: aula.quiz ? (aula.quiz.pergunta + '\n\nA) ' + aula.quiz.opcoes.A + '\n\nB) ' + aula.quiz.opcoes.B + '\n\nC) ' + aula.quiz.opcoes.C) : '' },
        action: {
          buttons: [
            { type: 'reply', reply: { id: 'quiz_A', title: 'Opção A' } },
            { type: 'reply', reply: { id: 'quiz_B', title: 'Opção B' } },
            { type: 'reply', reply: { id: 'quiz_C', title: 'Opção C' } }
          ]
        }
      }
    })
  }
};

