const aula = $input.first().json;
const usuario = $('Rotear Mensagem do Usuário').first().json;
const respostaUsuario = usuario.mensagem_original || (usuario.button_reply_id ? usuario.button_reply_id.replace('quiz_','') : '');
let telefone = usuario.telefone;
if (!telefone.startsWith('55')) telefone = '55' + telefone;
if (!telefone.startsWith('+')) telefone = '+' + telefone;

if (!aula || !aula.id) {
  return {
    json: {
      telefone,
      usuario_id: usuario.usuario_id,
      quiz_valido: false,
      badge_mensagem: null,
      badge_imagem_url: null,
      mensagem_feedback: '❓ Não encontrei um quiz pendente. Envie qualquer mensagem para acessar o menu.'
    }
  };
}

const quiz = aula.quiz;
const respostaCorreta = quiz.resposta_correta;
const acertou = respostaUsuario === respostaCorreta;
// Calcular streak em UTC puro (igual ao $now.toFormat do n8n no Railway)
const agora = new Date();
const hoje = agora.toISOString().split('T')[0];
const ontem = new Date(agora.getTime() - 86400000).toISOString().split('T')[0];
const ultimaAtividade = usuario.ultima_atividade || null;
const streakAtual = usuario.streak_atual || 0;
const novoStreak = (ultimaAtividade === ontem || ultimaAtividade === hoje)
  ? streakAtual + 1
  : 1;
const aulasCompletas = usuario.aula_atual;
const tema = usuario.tema || usuario.tema_escolhido;
// usuario.momento e usuario.horario_texto vêm do Extrair Status do Usuário via spread
const momento_dia = usuario.momento || 'Ao acordar';
const horario_texto = usuario.horario_texto || '6h';

const badgeUrls = {
  'Brasil Colônia': {
    7:  'https://res.cloudinary.com/dxq2reesi/image/upload/v1773167915/8b9d4480-fcd5-4e40-bba1-abf6befb2bcd.png',
    14: 'https://res.cloudinary.com/dxq2reesi/image/upload/v1773168421/1654673e-5583-4c88-8602-89baf731754f.png',
    21: 'https://res.cloudinary.com/dxq2reesi/image/upload/v1773168730/79a5f8ac-152e-4fe9-b7e1-2c5089523c71.png',
    30: 'https://res.cloudinary.com/dxq2reesi/image/upload/v1773168841/a36786d3-dac0-4090-b895-95367770b942.png'
  },
  'Egito Antigo': {
    7:  'https://res.cloudinary.com/dxq2reesi/image/upload/v1773168967/dec64efd-f9ba-4a65-b1ec-96bb016b2941.png',
    14: 'https://res.cloudinary.com/dxq2reesi/image/upload/v1773169169/2edb9aea-8be3-481d-8384-bbf0772a9c2a.png',
    21: 'https://res.cloudinary.com/dxq2reesi/image/upload/v1773169268/904be94a-878a-43eb-a8f9-643ecbd7a4c5.png',
    30: 'https://res.cloudinary.com/dxq2reesi/image/upload/v1773169352/5108f9c0-1db1-4f9b-b87d-13cdb54c9494.png'
  },
  'Idade Média': {
    7:  'https://res.cloudinary.com/dxq2reesi/image/upload/v1773169473/942aa950-7046-4c2b-abcc-66425a9d4755.png',
    14: 'https://res.cloudinary.com/dxq2reesi/image/upload/v1773169595/7d996c66-0edd-4bfd-9c34-b5bf8a9de807.png',
    21: 'https://res.cloudinary.com/dxq2reesi/image/upload/v1773171887/2f0413d1-3617-4406-b04e-8333e4d1cfe7.png',
    30: 'https://res.cloudinary.com/dxq2reesi/image/upload/v1773172085/b9a200d7-aa1b-4ed5-b1a1-2948b759113d.png'
  },
  'Império Romano': {
    7:  'https://res.cloudinary.com/dxq2reesi/image/upload/v1773172244/a92c1760-f8e1-45d1-aa1e-ff962229e323.png',
    14: 'https://res.cloudinary.com/dxq2reesi/image/upload/v1773172351/7e46875f-df1d-4d9c-8884-0c2430a77d22.png',
    21: 'https://res.cloudinary.com/dxq2reesi/image/upload/v1773172501/697d5dee-baa1-491b-9e98-1707e88402f4.png',
    30: 'https://res.cloudinary.com/dxq2reesi/image/upload/v1773172597/912cfe68-b8ac-4d64-b0a8-cecd38e2c9b5.png'
  },
  'Segunda Guerra Mundial': {
    7:  'https://res.cloudinary.com/dxq2reesi/image/upload/v1773172732/4c393aa4-432e-4801-a67d-0a82926bed10.png',
    14: 'https://res.cloudinary.com/dxq2reesi/image/upload/v1773172841/733be2f5-2121-4207-929e-8f1449924e99.png',
    21: 'https://res.cloudinary.com/dxq2reesi/image/upload/v1773172970/e4805372-d83a-4f9d-b8f4-d7f86f380060.png',
    30: 'https://res.cloudinary.com/dxq2reesi/image/upload/v1773173072/121529cb-1dfe-4fcb-9085-0832d98fd93d.png'
  }
};

const badgeNomes = {
  7: 'Aprendiz',
  14: 'Explorador',
  21: 'Conhecedor',
  30: 'Expert'
};

const badgeEmojis = {
  7: '🥉',
  14: '🗺️',
  21: '🥈',
  30: '🥇🎉'
};

let badgeMensagem = null;
let badgeImagemUrl = null;

if ([7, 14, 21, 30].includes(aulasCompletas)) {
  const nome = badgeNomes[aulasCompletas];
  const emoji = badgeEmojis[aulasCompletas];
  badgeImagemUrl = badgeUrls[tema]?.[aulasCompletas] || null;

  if (aulasCompletas === 30) {
    badgeMensagem = `Parabéns, ${usuario.nome}! Você concluiu todas as 30 aulas de *${tema}* e se tornou um *Expert*! 🥇🎉`;
  } else {
    badgeMensagem = `Parabéns! Você ganhou um novo badge! ${emoji} *${nome} de ${tema}*`;
  }
}

let mensagemFeedback = '';
if (acertou) {
  mensagemFeedback = `✅ *Correto, ${usuario.nome}!*\n\n${quiz.explicacao}\n\n🔥 Streak: ${novoStreak} dia${novoStreak > 1 ? 's' : ''} seguido${novoStreak > 1 ? 's' : ''}!`;
} else {
  const respostaCorretaTexto = quiz.opcoes[respostaCorreta];
  mensagemFeedback = `❌ *Não foi dessa vez, ${usuario.nome}!*\n\nA resposta correta era *${respostaCorreta})* — ${respostaCorretaTexto}\n\n${quiz.explicacao}\n\n🔥 Streak: ${novoStreak} dia${novoStreak > 1 ? 's' : ''} seguido${novoStreak > 1 ? 's' : ''}!`;
}

if (aulasCompletas < 30) {
  mensagemFeedback += `\n\n⏰ Sua próxima aula chega *${momento_dia}* (${horario_texto}). Até lá!`;
}

return {
  json: {
    telefone,
    usuario_id: usuario.usuario_id,
    aula_id: aula.id,
    quiz_valido: true,
    acertou,
    resposta_usuario: respostaUsuario,
    novo_streak: novoStreak,
    badge_mensagem: badgeMensagem,
    badge_imagem_url: badgeImagemUrl,
    mensagem_feedback: mensagemFeedback
  }
};

